export const getF2PSkills = () => skills.filter(s => s.membership === 'free');
export const getMembersSkills = () => skills.filter(s => s.membership === 'members');
export const getSkillsByCategory = (category: SkillCategory) => skills.filter(s => s.category === category);
export const getSkillByName = (name: string) => skills.find(s => s.name === name);
